/**
 * left-pad -> String.prototype.padStart (JavaScript, native).
 *
 * Why this pair: left-pad is the best-known dead package, and padStart looks like an exact
 * replacement. It is not. Running the séance finds four real differences (empty, multi-character
 * and non-string fill characters, and length coercion), which a reader of the deprecation notice
 * would never have guessed.
 */

import type { KnownDifference, SeanceBundle, SeanceFile } from '../../types.js';
import { callsNote, jsProjectCalls } from '../examples.js';
import { renderReadme } from '../readme.js';
import { makeBundle, type Mutant, type Recipe, type RecipeContext } from '../recipe.js';
import { depOfContext, oldVersionsFor } from '../versions.js';

const DIR = 'seance/left-pad';

export const LEFT_PAD_KNOWN: KnownDifference[] = [
  {
    input: 'leftPad("abc", 6, "")',
    old: '"   abc" (three spaces, then abc: an empty fill becomes a space)',
    naive: '"abc" (an empty fill pads nothing)',
    handled: 'Empty, null, undefined and false fill characters become a space, as before.',
  },
  {
    input: 'leftPad("abc", 6, "xy")',
    old: '"xyxyxyabc" (the whole fill is repeated once per missing character)',
    naive: '"xyxabc" (the fill is cut to the missing length)',
    handled: 'The fill is repeated once per missing character, as before.',
  },
  {
    input: 'leftPad("abc", 6, null)',
    old: '"   abc" (three spaces, then abc)',
    naive: '"nulabc" (null is turned into the text "null")',
    handled: 'null is treated like a missing fill character, as before.',
  },
  {
    input: 'leftPad("abc", Infinity, "-")',
    old: '"abc" (the length is truncated to 32 bits, so nothing is added)',
    naive: 'RangeError: Invalid string length',
    handled:
      'Lengths that are not finite add nothing, as before. Lengths of 2^31 or more are outside what the séance compares: left-pad wraps them around.',
  },
  {
    input: 'leftPad("abc", 5.5)',
    old: '"undefinedabc" (a bug: a fractional length below 10 with a space fill reads a missing cache entry)',
    naive: '"  abc"',
    handled:
      'Not reproduced on purpose: the replacement pads, as every caller meant. The séance does not compare this case and pins the old answer in a separate test.',
  },
];

function replacementSource(): string {
  return [
    '// Replacement for left-pad. Generated by Necromancer (recipe "left-pad").',
    '// Dependency-free. It answers like left-pad 1.3.0 for every input the séance compares.',
    '//',
    '// String.prototype.padStart is NOT a drop-in: it differs for an empty, multi-character or',
    "// non-string fill and for lengths that are not finite. This function keeps left-pad's answers.",
    "// If you decide that padStart's answers are what you want, call padStart directly and delete",
    '// the "naive" expectations in seance.test.mjs.',
    'export function leftPad(str, len, ch) {',
    "  str = str + '';",
    '  // left-pad counts the missing characters with a 32-bit truncation; Math.trunc is the same',
    '  // for every length the séance compares (below 2^31).',
    '  const missing = Math.trunc(len - str.length);',
    '  if (!(missing > 0) || !Number.isFinite(missing)) return str;',
    "  if (!ch && ch !== 0) ch = ' ';",
    "  return (ch + '').repeat(missing) + str;",
    '}',
    '',
  ].join('\n');
}

function testSource(projectCalls: string[]): string {
  return [
    '// Séance: left-pad -> String.prototype.padStart. Generated by Necromancer (recipe "left-pad").',
    '// Run: npx vitest run seance/left-pad',
    '//',
    '// Asks left-pad and the replacement the same generated questions and fails on any different',
    '// answer. Compared: the returned string or, when the call throws, the error class (never the',
    '// message). Lengths of 2^31 or more are not generated: left-pad wraps them around.',
    "import { describe, it, expect } from 'vitest';",
    "import fc from 'fast-check';",
    "import leftPadOld from 'left-pad';",
    "import { leftPad } from './replacement.mjs';",
    '',
    'const outcome = (fn, args) => {',
    '  try {',
    '    return { ok: true, value: fn(...args) };',
    '  } catch (e) {',
    '    return { ok: false, error: e && e.constructor ? e.constructor.name : typeof e };',
    '  }',
    '};',
    '',
    '// What a reader would try first. The séance shows it is not the same.',
    'const naive = (str, len, ch) => String(str).padStart(len, ch);',
    '',
    '// Generators: values the real function is called with, plus the awkward ones.',
    'const str = fc.oneof(',
    '  fc.string({ maxLength: 8 }),',
    "  fc.constantFrom('', ' ', 'abc', '\\u00e9', '\\ud83d\\ude00'),",
    '  fc.integer(),',
    '  fc.constantFrom(null, undefined, true, false, 0),',
    ');',
    'const len = fc.oneof(',
    '  fc.integer({ min: -5, max: 40 }),',
    '  fc.double({ min: -5, max: 40, noNaN: true }),',
    "  fc.constantFrom(NaN, Infinity, -Infinity, '7', '', '3.5', null, undefined, true),",
    ');',
    'const fill = fc.oneof(',
    '  fc.constant(undefined),',
    '  fc.constant(null),',
    '  fc.string({ maxLength: 3 }),',
    '  fc.integer({ min: 0, max: 9 }),',
    "  fc.constantFrom('', ' ', 0, false, true, NaN, '\\ud83d\\ude00'),",
    ');',
    '',
    '// left-pad bug, not reproduced: a fractional length below 10 with a space fill reads a',
    '// missing cache entry and answers "undefined" + str. The replacement pads instead.',
    'const oldBug = (s, n, c) => {',
    "  const missing = n - (s + '').length;",
    "  const space = (!c && c !== 0) || (c + '') === ' ';",
    '  return space && Number.isFinite(missing) && missing > 0 && missing < 10 && !Number.isInteger(missing);',
    '};',
    '',
    ...projectCalls,
    '',
    "describe('seance: left-pad -> String.prototype.padStart', () => {",
    "  it('the replacement answers like left-pad for any string, length and fill', () => {",
    '    fc.assert(',
    '      fc.property(str, len, fill, (s, n, c) => {',
    '        fc.pre(!oldBug(s, n, c));',
    '        expect(outcome(leftPad, [s, n, c])).toEqual(outcome(leftPadOld, [s, n, c]));',
    '      }),',
    '      { numRuns: 2000 },',
    '    );',
    '  });',
    '',
    "  it('the replacement answers like left-pad when the fill is left out', () => {",
    '    fc.assert(',
    '      fc.property(str, len, (s, n) => {',
    '        fc.pre(!oldBug(s, n, undefined));',
    '        expect(outcome(leftPad, [s, n])).toEqual(outcome(leftPadOld, [s, n]));',
    '      }),',
    '      { numRuns: 500 },',
    '    );',
    '  });',
    '',
    "  it('the replacement answers like left-pad on the calls this project makes', () => {",
    '    for (const args of projectCalls) {',
    '      expect(outcome(leftPad, args), JSON.stringify(args)).toEqual(outcome(leftPadOld, args));',
    '    }',
    '  });',
    '',
    '  // Known differences, found by this séance. Each input must still show a difference for',
    '  // the naive call; if one stops differing, the list is out of date.',
    "  const knownInputs = [['abc', 6, ''], ['abc', 6, 'xy'], ['abc', 6, null], ['abc', Infinity, '-']];",
    "  it('the naive String.prototype.padStart differs from left-pad on the known inputs', () => {",
    '    for (const args of knownInputs) {',
    '      expect(outcome(naive, args), JSON.stringify(args)).not.toEqual(outcome(leftPadOld, args));',
    '      expect(outcome(leftPad, args), JSON.stringify(args)).toEqual(outcome(leftPadOld, args));',
    '    }',
    '  });',
    '',
    "  it('the replacement pads where left-pad answers undefined (a left-pad bug, not reproduced)', () => {",
    '    expect(leftPadOld("abc", 5.5)).toBe("undefinedabc");',
    '    expect(leftPad("abc", 5.5)).toBe("  abc");',
    '  });',
    '',
    "  it('on the known inputs left-pad answers as documented', () => {",
    '    expect(leftPadOld("abc", 6, "")).toBe("   abc");',
    '    expect(leftPadOld("abc", 6, "xy")).toBe("xyxyxyabc");',
    '    expect(leftPadOld("abc", 6, null)).toBe("   abc");',
    '    expect(leftPadOld("abc", Infinity, "-")).toBe("abc");',
    '  });',
    '});',
    '',
  ].join('\n');
}

function build(ctx: RecipeContext): SeanceBundle {
  const pick = (m: string): boolean => m === 'default' || m === 'leftPad';
  const files: SeanceFile[] = [
    {
      path: `${DIR}/seance.test.mjs`,
      content: testSource(jsProjectCalls(ctx.usage, pick)),
      role: 'test',
    },
    { path: `${DIR}/replacement.mjs`, content: replacementSource(), role: 'replacement' },
  ];
  const compares = [
    'The returned string, or the error class when the call throws (never the message).',
    'Strings, numbers, null, undefined and booleans as the text; lengths that are integers, fractions, numeric strings, NaN and infinities; empty, multi-character and non-string fill characters.',
    'Not compared: lengths of 2^31 or more (left-pad wraps them around).',
    callsNote(ctx.usage, pick),
  ];
  const install = ['npm install --save-dev vitest fast-check'];
  const oldVersions = oldVersionsFor('left-pad', depOfContext(ctx));
  compares.push(`Versions: ${oldVersions.note}`);
  const run = 'npx vitest run seance/left-pad';
  const readme = renderReadme({
    title: 'left-pad to String.prototype.padStart',
    recipe: 'left-pad',
    files: [
      { path: `${DIR}/seance.test.mjs`, what: 'the differential property test' },
      {
        path: `${DIR}/replacement.mjs`,
        what: "the replacement to adopt (keeps left-pad's answers)",
      },
    ],
    install,
    run,
    compares,
    known: LEFT_PAD_KNOWN,
    versions: oldVersions.note,
  });
  files.push({ path: `${DIR}/README.md`, content: readme, role: 'readme' });
  return makeBundle({
    language: 'javascript',
    recipe: 'left-pad',
    title: 'left-pad to String.prototype.padStart',
    files,
    install,
    run,
    compares,
    knownDifferences: LEFT_PAD_KNOWN,
    members: ['default'],
    oldVersions,
  });
}

function mutants(): Mutant[] {
  const path = `${DIR}/replacement.mjs`;
  return [
    {
      id: 'naive-padStart',
      description: 'calls String.prototype.padStart directly (the obvious migration)',
      files: [
        {
          path,
          role: 'replacement',
          content:
            'export function leftPad(str, len, ch) { return String(str).padStart(len, ch); }\n',
        },
      ],
    },
    {
      id: 'off-by-one',
      description: 'pads one character too few',
      files: [
        {
          path,
          role: 'replacement',
          content: [
            'export function leftPad(str, len, ch) {',
            "  str = str + '';",
            '  const missing = Math.trunc(len - str.length) - 1;',
            '  if (!(missing > 0) || !Number.isFinite(missing)) return str;',
            "  if (!ch && ch !== 0) ch = ' ';",
            "  return (ch + '').repeat(missing) + str;",
            '}',
            '',
          ].join('\n'),
        },
      ],
    },
  ];
}

export const leftPadRecipe: Recipe = {
  id: 'left-pad',
  language: 'javascript',
  ecosystem: 'npm',
  old: 'left-pad',
  successors: ['String.prototype.padStart', 'padStart'],
  why: 'The best-known dead package; the obvious native replacement is subtly different.',
  build,
  mutants,
};
